#include "cuda_utils.cuh"
#include <vector>
#include <iostream>
#define BW 16
__constant__ float filt[9];
__global__ void conv2d(const float* in,float* out,int H,int W){constexpr int R=1;__shared__ float tile[BW+2][BW+2];int tx=threadIdx.x,ty=threadIdx.y;int ox=blockIdx.x*BW+tx,oy=blockIdx.y*BW+ty;int sx=tx+R,sy=ty+R;tile[sy][sx]=(ox<W&&oy<H)?in[oy*W+ox]:0;if(tx==0)tile[sy][0]=(ox-1>=0&&oy<H)?in[oy*W+ox-1]:0;if(tx==BW-1)tile[sy][BW+1]=(ox+1<W&&oy<H)?in[oy*W+ox+1]:0;if(ty==0)tile[0][sx]=(oy-1>=0&&ox<W)?in[(oy-1)*W+ox]:0;if(ty==BW-1)tile[BW+1][sx]=(oy+1<H&&ox<W)?in[(oy+1)*W+ox]:0;if(tx==0&&ty==0)tile[0][0]=(ox>0&&oy>0)?in[(oy-1)*W+ox-1]:0;if(tx==BW-1&&ty==0)tile[0][BW+1]=(ox+1<W&&oy>0)?in[(oy-1)*W+ox+1]:0;if(tx==0&&ty==BW-1)tile[BW+1][0]=(ox>0&&oy+1<H)?in[(oy+1)*W+ox-1]:0;if(tx==BW-1&&ty==BW-1)tile[BW+1][BW+1]=(ox+1<W&&oy+1<H)?in[(oy+1)*W+ox+1]:0;__syncthreads();if(ox<W&&oy<H){float s=0;for(int ky=0;ky<3;ky++)for(int kx=0;kx<3;kx++)s+=tile[sy+ky-1][sx+kx-1]*filt[ky*3+kx];out[oy*W+ox]=s;}}
int main(){int H=257,W=333,n=H*W;std::vector<float>x(n),y(n),r(n);float f[9]={0,-1,0,-1,5,-1,0,-1,0};for(int i=0;i<n;i++)x[i]=(i%101)/101.f;for(int yy=0;yy<H;yy++)for(int xx=0;xx<W;xx++){float s=0;for(int ky=-1;ky<=1;ky++)for(int kx=-1;kx<=1;kx++){int y2=yy+ky,x2=xx+kx;if(x2>=0&&x2<W&&y2>=0&&y2<H)s+=x[y2*W+x2]*f[(ky+1)*3+kx+1];}r[yy*W+xx]=s;}float *dx,*dy;CUDA_CHECK(cudaMalloc(&dx,n*4));CUDA_CHECK(cudaMalloc(&dy,n*4));CUDA_CHECK(cudaMemcpy(dx,x.data(),n*4,cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpyToSymbol(filt,f,sizeof(f)));dim3 block(BW,BW),grid((W+BW-1)/BW,(H+BW-1)/BW);conv2d<<<grid,block>>>(dx,dy,H,W);check_kernel("conv2d");CUDA_CHECK(cudaMemcpy(y.data(),dy,n*4,cudaMemcpyDeviceToHost));for(int i=0;i<n;i++)if(!nearly_equal(y[i],r[i],1e-4f,1e-4f)){std::cerr<<"FAIL "<<i<<"\n";return 1;}CUDA_CHECK(cudaFree(dx));CUDA_CHECK(cudaFree(dy));std::cout<<"PASS\n";}
